const HOSTED=true;
// Target Google Spreadsheet (reference only; Apps Script Code.gs uses this ID to save data).
const GOOGLE_SPREADSHEET_ID = '1MimGbYNBqVbDLOxC7TIVv8IQImNCPkxSgnmjq94NxnQ';
// IMPORTANT: Spreadsheet edit URL is NOT the Apps Script Web App URL.
// After deploying Code.gs as a Web App, paste its https://script.google.com/macros/s/.../exec URL here.
const APPS_SCRIPT_WEB_APP_URL = 'PASTE_YOUR_GOOGLE_APPS_SCRIPT_EXEC_URL_HERE';
// GitHub frontend -> embedded Google Apps Script bridge -> Sheets/Drive.
const BRIDGE_CHANNEL='raj-cheque-v5';
let bridgeFrame=null, bridgeReady=null, bridgeResolve=null;
const requests=new Map();
window.addEventListener('message',event=>{
 if(!bridgeFrame || event.source!==bridgeFrame.contentWindow)return;
 // The Apps Script HTML sandbox uses a googleusercontent.com origin.
 if(!/^https:\/\/[a-z0-9.-]*googleusercontent\.com$/i.test(event.origin) && !/^https:\/\/script\.google\.com$/i.test(event.origin))return;
 const m=event.data;
 if(!m||m.channel!==BRIDGE_CHANNEL)return;
 if(m.type==='ready'){if(bridgeResolve){bridgeResolve();bridgeResolve=null;}return;}
 if(m.type==='response'&&requests.has(m.id)){const q=requests.get(m.id);requests.delete(m.id);clearTimeout(q.timer);if(m.ok)q.resolve(m.data);else q.reject(new Error(m.error||'Apps Script error'));}
});
function ensureBridge(){
 if(bridgeReady)return bridgeReady;
 if(!/^https:\/\/script\.google\.com\/macros\/s\/.+\/exec(?:\?|$)/.test(APPS_SCRIPT_WEB_APP_URL))return Promise.reject(Error('script.js mein APPS_SCRIPT_WEB_APP_URL paste karein.'));
 bridgeFrame=document.createElement('iframe');bridgeFrame.src=APPS_SCRIPT_WEB_APP_URL;
 bridgeFrame.title='Google Sheets connection';bridgeFrame.style.cssText='position:absolute;width:1px;height:1px;opacity:0;pointer-events:none;border:0';
 document.body.appendChild(bridgeFrame);
 bridgeReady=new Promise((resolve,reject)=>{
  bridgeResolve=resolve;
  const timer=setInterval(()=>{try{bridgeFrame.contentWindow.postMessage({channel:BRIDGE_CHANNEL,type:'ping'},'*')}catch(e){}},700);
  setTimeout(()=>{clearInterval(timer);if(bridgeResolve){bridgeResolve=null;bridgeReady=null;reject(Error('Apps Script connection timeout. Check web app access / Bridge.html allowlist / browser third-party cookies.'));}},25000);
  const original=bridgeResolve;bridgeResolve=()=>{clearInterval(timer);original()};
 });
 return bridgeReady;
}
function api(action,args=[]){
 if(!authToken) return Promise.reject(Error('Please sign in'));
 return ensureBridge().then(()=>new Promise((resolve,reject)=>{
  let id=Date.now()+'-'+Math.random().toString(36).slice(2);
  const timer=setTimeout(()=>{requests.delete(id);reject(Error('Google Apps Script request timed out'))},90000);
  requests.set(id,{resolve,reject,timer});
  bridgeFrame.contentWindow.postMessage({channel:BRIDGE_CHANNEL,type:'request',id,action,args},'*');
 }));
}

const PASS_KEY='raj-group-browser-password-hash-v4';
const AUTH_KEY='raj-group-browser-unlocked-v4';
const SESSION_OK='yes';
let authToken=sessionStorage.getItem(AUTH_KEY)===SESSION_OK?SESSION_OK:'';
async function hashText(value){
 const bytes=new TextEncoder().encode(value);
 const digest=await crypto.subtle.digest('SHA-256',bytes);
 return [...new Uint8Array(digest)].map(v=>v.toString(16).padStart(2,'0')).join('');
}
function showLogin(){
 document.getElementById('loginPanel').style.display='flex';
 document.getElementById('logoutButton').style.display='none';
 document.getElementById('connectionState').textContent='● Signed out';
 document.getElementById('loginHeading').textContent=localStorage.getItem(PASS_KEY)?'RAJ GROUP · Login':'RAJ GROUP · Set Password';
 document.getElementById('loginSubmit').textContent=localStorage.getItem(PASS_KEY)?'Sign In':'Set Password & Continue';
}
function showLoggedIn(){
 document.getElementById('loginPanel').style.display='none';
 document.getElementById('logoutButton').style.display='inline-block';
 document.getElementById('connectionState').textContent='● Logged in · Google Sheets backend';
}
document.getElementById('loginForm').addEventListener('submit',async e=>{
 e.preventDefault();const input=document.getElementById('loginPassword');const error=document.getElementById('loginError');
 try{
  const pw=input.value;
  if(pw.length<8)throw Error('Password at least 8 characters ka rakhein.');
  const hashed=await hashText(pw),saved=localStorage.getItem(PASS_KEY);
  if(saved&&hashed!==saved)throw Error('Incorrect password');
  if(!saved)localStorage.setItem(PASS_KEY,hashed);
  authToken=SESSION_OK;sessionStorage.setItem(AUTH_KEY,SESSION_OK);
  input.value='';error.textContent='';showLoggedIn();await load();
 }catch(err){error.textContent=err.message}
});
document.getElementById('logoutButton').onclick=()=>{authToken='';sessionStorage.removeItem(AUTH_KEY);records=[];render();showLogin()};
const ids=['returnDate','chequeDate','party','city','chequeNo','amount','reason','division','mh'];
const $=id=>document.getElementById(id);let masters=JSON.parse(JSON.stringify(DEFAULTS)),records=[],editingId='',page=1,limit=100,loadIndex=0;
const currentYear=()=>$('year').value;
function toast(msg){const e=$('toast');e.textContent=msg;e.style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.style.display='none',3800)}
function server(method,...args){return Promise.reject(new Error("Google Sheets backend is NOT connected. This version uses browser storage only."))}
function localKey(){return 'rajgroup-cheque-return-'+currentYear()}
function norm(v){return String(v||'').trim().toLocaleLowerCase()}
function dateFormat(value){
 let s=String(value||'').trim(),d,m,y,parts,yr=new Date().getFullYear();
 if(/^\d{4}$/.test(s)){d=+s.slice(0,2);m=+s.slice(2);y=yr}
 else if(/^\d{6}$/.test(s)){d=+s.slice(0,2);m=+s.slice(2,4);y=2000+Number(s.slice(4))}
 else if(/^\d{8}$/.test(s)){d=+s.slice(0,2);m=+s.slice(2,4);y=+s.slice(4)}
 else if(/^\d{1,2}[\/.-]\d{1,2}$/.test(s)){parts=s.split(/[\/.-]/).map(Number);[d,m]=parts;y=yr}
 else if(/^\d{1,2}[\/.-]\d{1,2}[\/.-]\d{2,4}$/.test(s)){parts=s.split(/[\/.-]/).map(Number);[d,m,y]=parts;if(y<100)y+=2000}
 else return null;
 let x=new Date(y,m-1,d);if(x.getFullYear()!==y||x.getMonth()!==m-1||x.getDate()!==d)return null;
 return [String(d).padStart(2,'0'),String(m).padStart(2,'0'),y].join('/');
}
function todayDate(){let now=new Date();return [String(now.getDate()).padStart(2,'0'),String(now.getMonth()+1).padStart(2,'0'),now.getFullYear()].join('/')}
function detectCity(party){
 // Only infer from a trailing city name to avoid false matches (e.g. city inside a business name).
 // Prefer longest names first: 'New Surat' before 'Surat'. If ambiguous, leave blank.
 let p=norm(party).replace(/[^\p{L}\p{N}]+/gu,' ').trim();if(!p)return '';
 let hits=(masters.city||[]).filter(c=>{let z=norm(c).replace(/[^\p{L}\p{N}]+/gu,' ').trim();return z&&p.endsWith(' '+z)}).sort((a,b)=>b.length-a.length);
 if(!hits.length)return '';
 let top=hits[0],topNorm=norm(top);if(hits.slice(1).some(c=>c.length===top.length&&norm(c)!==topNorm))return '';
 return top;
}
function autoCity(){ $('city').value=detectCity($('party').value) }

function money(n){return '₹'+Number(n||0).toLocaleString('en-IN',{maximumFractionDigits:2,minimumFractionDigits:2})}
function sanitize(text){return String(text??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function showBanner(){const el=$('banner');el.className='notice'+(HOSTED?'':' warn');el.textContent=HOSTED?'🟢 Google Apps Script mode — entries are saved in connected Google Sheet.':'🟡 BROWSER-ONLY MODE — Password is just a screen lock. Records are saved ONLY in this browser, NOT Google Sheets. Do not enter sensitive/live cheque details.'}
async function load(){let key=++loadIndex;$('selYear').textContent=$('listYear').textContent=currentYear();$('saveStatus').textContent='Loading...';try{if(HOSTED){let data=await server('getBootstrap',currentYear());if(key!==loadIndex)return;records=data.records||[];if(data.masters)masters=data.masters}else{records=JSON.parse(localStorage.getItem(localKey())||'[]');masters=JSON.parse(localStorage.getItem('rajgroup-masters')||'null')||JSON.parse(JSON.stringify(DEFAULTS))}page=1;render();$('saveStatus').textContent='Google Sheet connected';$('banner').className='notice';$('banner').textContent='🟢 Google Sheets connected — secure saving and private cheque images enabled.';}catch(e){$('saveStatus').textContent='Error: '+e.message;$('banner').className='notice warn';$('banner').textContent='Connection failed: '+e.message;toast(e.message)}}
function filtered(){const q=norm($('filter').value);if(!q)return records;return records.filter(r=>['returnDate','chequeDate','party','city','chequeNo','amount','reason','division','mh','entryDate'].some(k=>norm(r[k]).includes(q)))}
function render(){let arr=filtered(),sum=records.reduce((a,r)=>a+(Number(r.amount)||0),0);$('count').textContent=records.length.toLocaleString('en-IN');$('sum').textContent=money(sum);const pages=Math.max(1,Math.ceil(arr.length/limit));page=Math.min(page,pages);let view=arr.slice((page-1)*limit,page*limit);$('shown').textContent=arr.length+' visible of '+records.length+' records';$('pageInfo').textContent='Page '+page+' / '+pages;$('prevBtn').disabled=page<=1;$('nextBtn').disabled=page>=pages;
 $('rows').innerHTML=view.length?view.map(r=>`<tr><td>${sanitize(r.returnDate)}</td><td>${sanitize(r.chequeDate)}</td><td><b>${sanitize(r.party)}</b></td><td>${sanitize(r.city)}</td><td>${sanitize(r.chequeNo)}</td><td class="num">${money(r.amount)}</td><td>${sanitize(r.reason)}</td><td>${sanitize(r.division)}</td><td>${sanitize(r.mh)}</td><td>${sanitize(r.entryDate||'—')}</td><td>${r.imageId?`<button class="rowbtn" data-act="view" data-id="${sanitize(r.id)}">👁 View Image</button>`:'—'}</td><td style="white-space:nowrap"><button class="rowbtn" data-act="edit" data-id="${sanitize(r.id)}">Edit</button> <button class="rowbtn red" data-act="delete" data-id="${sanitize(r.id)}">Delete</button></td></tr>`).join(''):'<tr><td class="empty" colspan="10">No matching entries. Use the entry form above.</td></tr>'}
function resetForm(){$('entry').reset();editingId='';$('entryDate').value=todayDate();$('attachedInfo').textContent='';$('formTitle').textContent='✦ New Cheque Return Entry';$('saveBtn').textContent='✚ Save Entry';$('returnDate').focus()}
function getForm(){return Object.fromEntries(ids.map(k=>[k,$(k).value.trim()]))}
function persistLocal(){localStorage.setItem(localKey(),JSON.stringify(records))}
function readPhoto(file){return new Promise((resolve,reject)=>{if(!file)return resolve(null);if(!['image/jpeg','image/png','image/webp'].includes(file.type))return reject(Error('Only JPG, PNG, WEBP allowed'));if(file.size>4*1024*1024)return reject(Error('Image 4 MB se chhoti rakhein'));let fr=new FileReader();fr.onerror=()=>reject(Error('Cannot read image'));fr.onload=()=>resolve({mime:file.type,base64:String(fr.result).split(',')[1]});fr.readAsDataURL(file)})}
async function openImage(r){const modal=$('photoModal'),body=$('photoContent');$('photoTitle').textContent=r.party+' • '+r.chequeNo;body.textContent='Loading cheque photo...';modal.style.display='flex';try{let x;if(HOSTED)x=await server('getChequePhoto',currentYear(),r.id);else x=r.localPhoto;if(!x||!x.base64)throw Error('Image not available');const img=new Image();img.alt='Cheque photo';img.src='data:'+x.mime+';base64,'+x.base64;body.replaceChildren(img)}catch(e){body.textContent='Image loading error: '+e.message}}
