$('entry').addEventListener('submit',async e=>{e.preventDefault();let r=getForm();for(const key of ['returnDate','chequeDate']){let d=dateFormat(r[key]);if(!d){$(key).focus();return toast('Invalid date: '+r[key]+' — 1910 / 19-10 / 191026 likhein')}r[key]=d;$(key).value=d}if(!r.party||!r.chequeNo)return toast('Party and Cheque Number are required');r.amount=Number(r.amount)||0;r.id=editingId||'';r.entryDate=$('entryDate').value;let duplicate=records.some(x=>x.id!==editingId&&norm(x.chequeNo)===norm(r.chequeNo)&&norm(x.party)===norm(r.party)&&x.returnDate===r.returnDate);if(duplicate&&!confirm('Same Party, Return Date aur Cheque Number ki entry pehle se hai. Phir bhi save karna hai?'))return;
 $('saveBtn').disabled=true;$('saveStatus').textContent='Saving...';try{let photo=await readPhoto($('chequeImage').files[0]);if(HOSTED){let result=await server('saveRecord',currentYear(),r,photo);r.id=result.id;r.entryDate=result.entryDate;r.imageId=result.imageId}else{r.id=r.id||('local-'+Date.now()+'-'+Math.random().toString(36).slice(2));const old=records.find(x=>x.id===r.id);r.entryDate=old?.entryDate||todayDate();r.imageId=photo?'demo-photo':(old?.imageId||'');r.localPhoto=photo||(old?.localPhoto||null)}let i=records.findIndex(x=>x.id===r.id);if(i>=0)records[i]=r;else records.unshift(r);if(!HOSTED)persistLocal();render();resetForm();$('saveStatus').textContent='✓ Saved';toast('Entry saved successfully');}catch(e){toast('Save failed: '+e.message);$('saveStatus').textContent='Save failed'}finally{$('saveBtn').disabled=false}});
$('rows').addEventListener('click',async e=>{const b=e.target.closest('button[data-act]');if(!b)return;let r=records.find(x=>x.id===b.dataset.id);if(!r)return;if(b.dataset.act==='view'){await openImage(r);return}if(b.dataset.act==='edit'){editingId=r.id;ids.forEach(k=>$(k).value=r[k]??'');$('entryDate').value=r.entryDate||'—';$('chequeImage').value='';$('attachedInfo').textContent=r.imageId?'Existing image attached; select a file to replace it.':'';$('formTitle').textContent='✎ Edit Cheque Return Entry';$('saveBtn').textContent='✓ Update Entry';window.scrollTo({top:0,behavior:'smooth'});$('party').focus();return}if(!confirm('Is cheque return record ko permanently DELETE karna hai?'))return;try{if(HOSTED)await server('deleteRecord',currentYear(),r.id);records=records.filter(x=>x.id!==r.id);if(!HOSTED)persistLocal();render();toast('Entry deleted')}catch(err){toast('Delete failed: '+err.message)}});
$('resetBtn').onclick=resetForm;$('year').onchange=()=>{resetForm();$('filter').value='';load()};$('filter').oninput=()=>{page=1;render()};$('prevBtn').onclick=()=>{page--;render()};$('nextBtn').onclick=()=>{page++;render()};$('refreshBtn').onclick=load;
function csvEscape(v){let s=String(v??'');if(/^[=+@\-\t\r]/.test(s)&&isNaN(Number(s)))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
$('exportBtn').onclick=()=>{let cols=['returnDate','chequeDate','party','city','chequeNo','amount','reason','division','mh','entryDate'],headers=['Return Chq. Date','Chq. Date','Party Name','City','Chq. No.','Chq. Amt','Reason','Division','MH','Entry Date'];let lines=[headers.map(csvEscape).join(','),...filtered().map(r=>cols.map(c=>csvEscape(r[c])).join(','))].join('\r\n');let a=document.createElement('a'),url=URL.createObjectURL(new Blob(['\ufeff'+lines],{type:'text/csv;charset=utf-8;'}));a.href=url;a.download='RAJ_GROUP_'+currentYear()+'_Cheque_Returns.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
// Two-or-more words also match even when nonadjacent (e.g. "ag auto" -> A G Auto Parts).
function masterResults(type,query){let q=norm(query).replace(/[^\p{L}\p{N}]+/gu,' ').trim(),words=q.split(/\s+/).filter(Boolean);let list=masters[type]||[];if(!q)return list.slice(0,35);return list.filter(v=>{let n=norm(v).replace(/[^\p{L}\p{N}]+/gu,' ');return n.includes(q)||words.every(w=>n.split(' ').some(part=>part.startsWith(w)))}).slice(0,55)}
let opened=null;document.querySelectorAll('[data-master]').forEach(input=>{let popup=document.createElement('div');popup.className='suggest';input.parentNode.appendChild(popup);let active=-1,choices=[];const close=()=>{popup.classList.remove('open');opened=null};const select=i=>{if(!choices[i])return;input.value=choices[i];close();input.dispatchEvent(new Event('change'))};const draw=()=>{choices=masterResults(input.dataset.master,input.value);active=-1;popup.innerHTML=choices.length?choices.map((v,i)=>`<button type="button" data-i="${i}">${sanitize(v)}</button>`).join(''):'<button type="button" disabled>No matching item — add with + Add Dropdown Item</button>';popup.classList.toggle('open',true);opened=close};input.addEventListener('focus',draw);input.addEventListener('input',draw);input.addEventListener('keydown',e=>{if(!popup.classList.contains('open'))return;if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();active=(active+(e.key==='ArrowDown'?1:-1)+choices.length)%Math.max(choices.length,1);Array.from(popup.querySelectorAll('button')).forEach((b,i)=>b.classList.toggle('active',i===active));popup.querySelector('.active')?.scrollIntoView({block:'nearest'})}else if(e.key==='Enter'&&active>=0){e.preventDefault();select(active)}else if(e.key==='Escape')close()});popup.addEventListener('mousedown',e=>{let b=e.target.closest('[data-i]');if(b){e.preventDefault();select(Number(b.dataset.i))}});input.addEventListener('blur',()=>setTimeout(close,150))});
document.addEventListener('click',e=>{if(!e.target.closest('.field')&&opened)opened()});['returnDate','chequeDate'].forEach(id=>$(id).addEventListener('blur',function(){let d=dateFormat(this.value);if(d)this.value=d}));
$('addMasterBtn').onclick=()=>{$('modal').style.display='flex';$('newMasterValue').focus()};$('cancelMaster').onclick=()=>{$('modal').style.display='none'};$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').style.display='none'};
$('confirmMaster').onclick=async()=>{let type=$('masterType').value,value=$('newMasterValue').value.trim();if(!value)return toast('Please enter a value');if((masters[type]||[]).some(v=>norm(v)===norm(value)))return toast('Item already exists');try{if(HOSTED)await server('addMasterItem',type,value);masters[type].push(value);masters[type].sort((a,b)=>a.localeCompare(b));if(!HOSTED)localStorage.setItem('rajgroup-masters',JSON.stringify(masters));$(type).value=value;$('newMasterValue').value='';$('modal').style.display='none';toast('Dropdown item added')}catch(e){toast('Failed: '+e.message)}};
$('initBtn').onclick=async()=>{if(!HOSTED)return toast('Google Sheets initialization requires Apps Script deployment. Follow README.');if(!confirm('Google Sheet mein 4 year sheets aur DROP DOWN master list set up karna hai? Existing master data overwrite nahi hoga.'))return;let btn=$('initBtn');btn.disabled=true;try{let x=await server('initializeDatabase',DEFAULTS);toast('Google Sheet ready! '+x.counts.party+' parties loaded');await load()}catch(e){toast('Setup failed: '+e.message)}finally{btn.disabled=false}};
$('entryDate').value=todayDate();if(authToken){showLoggedIn();load()}else{showLogin();$('banner').textContent='Password screen lock · entries save to Google Sheets after backend setup.'}
